const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and time period
  const paradise = ee.Geometry.Point([-121.6219, 39.7596]); // Paradise, CA
  const buffer = paradise.buffer(10000); // 10km radius
  const startDate = '2018-11-07';
  const endDate = '2018-11-11'; // Inclusive of Nov 10

  console.log("Analyzing fire activity near Paradise, CA");
  console.log("Date range: Nov 7-10, 2018");
  console.log("Search radius: 10km");

  // 2. Try MODIS Terra Thermal Anomalies (MOD14A1)
  let fireCol = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(buffer);

  let colSize = fireCol.size().getInfo();
  console.log(`MODIS Terra images found: ${colSize}`);

  // 3. If no Terra data, try Aqua
  if (colSize === 0) {
    fireCol = ee.ImageCollection('MODIS/006/MYD14A1')
      .filterDate(startDate, endDate)
      .filterBounds(buffer);

    colSize = fireCol.size().getInfo();
    console.log(`MODIS Aqua images found: ${colSize}`);
  }

  // 4. Check if any images exist
  if (colSize === 0) {
    console.log("No MODIS fire data available for this period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Process fire detection
  // FireMask band: 0-8 with values 7-9 indicating fires
  const fireDetection = fireCol.map(function(img) {
    const fireMask = img.select('FireMask');
    // Fire pixels have values >= 7 (7=low confidence, 8=nominal, 9=high confidence)
    const fire = fireMask.gte(7);
    return fire.selfMask();
  });

  const fireComposite = fireDetection.max();

  // 6. Count fire pixels
  const fireStats = fireComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  });

  const firePixelCount = fireStats.get('FireMask').getInfo();

  // 7. Get maximum fire radiative power for context
  const frpStats = fireCol.select('MaxFRP').max().reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  });

  const maxFRP = frpStats.get('MaxFRP').getInfo();

  // 8. Validation and output
  console.log(`Fire pixels detected: ${firePixelCount || 0}`);
  console.log(`Maximum Fire Radiative Power: ${maxFRP || 0} MW`);

  if (firePixelCount === null || firePixelCount === undefined) {
    console.log("Calculation failed - unable to determine fire presence.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (firePixelCount === 0) {
    console.log("No fire pixels detected in the area during this period.");
    console.log("<answer>B</answer>");
  } else {
    console.log("Active fire detected during this period.");
    console.log("<answer>A</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
